package com.streamerpopoutpanels.tracker;

import com.streamerpopoutpanels.ui.SkillsView;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Tracks XP gained since the plugin started (or the session was reset). Session time only
 * counts time spent logged in. All methods run on the client thread.
 */
public class XpSessionTracker extends SnapshotPublisher<XpSession>
{
	/**
	 * Ticks after login during which stat changes only set the baseline, so the XP loaded at
	 * login doesn't count as gained.
	 */
	private static final int GRACE_TICKS = 2;
	private static final double SECONDS_PER_TICK = 0.6;

	private final Client client;
	private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);
	private final Map<Skill, Long> gained = new EnumMap<>(Skill.class);
	private boolean ready;
	private int ticksSinceLogin;
	private long sessionTicks;

	@Inject
	XpSessionTracker(Client client)
	{
		this.client = client;
	}

	/**
	 * Call on the client thread when the plugin starts while already logged in.
	 */
	public void startLoggedIn()
	{
		setBaseline();
		ready = true;
		publish();
	}

	public void reset()
	{
		gained.clear();
		sessionTicks = 0;
		publish();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Integer previous = lastXp.put(event.getSkill(), event.getXp());
		if (ready && previous != null && event.getXp() > previous)
		{
			gained.merge(event.getSkill(), (long) (event.getXp() - previous), Long::sum);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			lastXp.clear();
			ready = false;
			ticksSinceLogin = 0;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!ready && ++ticksSinceLogin >= GRACE_TICKS)
		{
			setBaseline();
			ready = true;
		}
		if (ready)
		{
			sessionTicks++;
		}
		publish();
	}

	private void setBaseline()
	{
		for (Skill skill : SkillsView.LAYOUT)
		{
			lastXp.putIfAbsent(skill, client.getSkillExperience(skill));
		}
	}

	private void publish()
	{
		double hours = sessionTicks * SECONDS_PER_TICK / 3600;
		List<XpSession.SkillGain> skills = new ArrayList<>();
		long total = 0;

		for (Map.Entry<Skill, Long> entry : gained.entrySet())
		{
			Skill skill = entry.getKey();
			long skillGained = entry.getValue();
			total += skillGained;

			int xp = lastXp.getOrDefault(skill, client.getSkillExperience(skill));
			int level = Experience.getLevelForXp(xp);
			long perHour = hours > 0 ? (long) (skillGained / hours) : 0;

			double progress = 1;
			long xpToLevel = 0;
			long secondsToLevel = -1;
			if (level < Experience.MAX_VIRT_LEVEL)
			{
				int levelStart = Experience.getXpForLevel(level);
				int levelEnd = Experience.getXpForLevel(level + 1);
				progress = (xp - levelStart) / (double) (levelEnd - levelStart);
				xpToLevel = levelEnd - xp;
				if (perHour > 0)
				{
					secondsToLevel = xpToLevel * 3600 / perHour;
				}
			}

			skills.add(new XpSession.SkillGain(skill, skillGained, perHour, level, progress, xpToLevel, secondsToLevel));
		}

		skills.sort(Comparator.comparingLong(XpSession.SkillGain::getGained).reversed());
		long totalPerHour = hours > 0 ? (long) (total / hours) : 0;
		publish(new XpSession((long) (sessionTicks * SECONDS_PER_TICK), total, totalPerHour, skills));
	}
}

package com.streamerpopoutpanels.ui;

import com.streamerpopoutpanels.Achievement;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;

/**
 * Recent achievements, newest first.
 */
public class AchievementsView extends ListView
{
	private static final int ROW_H = 40;
	private static final int ICON = 24;

	private final SkillIconManager skillIconManager;
	private List<Achievement> entries = new ArrayList<>();

	public AchievementsView(SkillIconManager skillIconManager)
	{
		this.skillIconManager = skillIconManager;
	}

	/**
	 * @param entries achievements, newest first
	 */
	public void setEntries(List<Achievement> entries)
	{
		this.entries = entries;
		contentChanged();
	}

	@Override
	protected boolean anyHighlighted()
	{
		return entries.stream().anyMatch(a -> highlightStrength(a.getTimestamp()) > 0);
	}

	@Override
	protected void paintContent(Graphics2D g)
	{
		if (entries.isEmpty())
		{
			drawEmpty(g, "No achievements yet");
			return;
		}

		int y = PADDING;
		for (Achievement a : entries)
		{
			if (y + ROW_H > naturalHeight())
			{
				break;
			}

			int x = PADDING;
			drawSlot(g, x, y, ROW_W, ROW_H);
			drawHighlight(g, x, y, ROW_W, ROW_H, highlightStrength(a.getTimestamp()));

			Color typeColor = a.getType().getColor();
			g.setColor(typeColor);
			g.fillRect(x, y + 4, 3, ROW_H - 8);

			int iconX = x + 8;
			BufferedImage icon = skillIcon(a.getSkill());
			if (icon != null)
			{
				drawIcon(g, icon, iconX, y + (ROW_H - ICON) / 2, ICON);
			}
			else
			{
				g.setColor(Draw.withAlpha(typeColor, 200));
				g.fillOval(iconX + 4, y + (ROW_H - 16) / 2, 16, 16);
			}

			int textX = iconX + ICON + 8;
			int textW = x + ROW_W - textX - 6;

			g.setFont(FontManager.getRunescapeSmallFont());
			Draw.shadowed(g, a.getType().getLabel(), textX, y + 14, typeColor);

			g.setFont(FontManager.getRunescapeFont());
			Draw.shadowed(g, Draw.truncate(a.getText(), g.getFontMetrics(), textW), textX, y + 32, Color.WHITE);

			y += ROW_H + ROW_GAP;
		}
	}

	private BufferedImage skillIcon(String skillName)
	{
		if (skillName == null)
		{
			return null;
		}
		try
		{
			return skillIconManager.getSkillImage(Skill.valueOf(skillName), false);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}
}

package com.streamerpopoutpanels.ui;

import com.streamerpopoutpanels.tracker.BossRecord;
import java.awt.Color;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.ui.FontManager;

/**
 * Kill counts and personal bests, most recently killed first.
 */
public class BossLogView extends ListView
{
	private static final int ROW_H = 38;

	private List<BossRecord> records = new ArrayList<>();

	public void setRecords(List<BossRecord> records)
	{
		this.records = records;
		contentChanged();
	}

	@Override
	protected boolean anyHighlighted()
	{
		return records.stream().anyMatch(r -> highlightStrength(r.getPersonalBestSet()) > 0);
	}

	@Override
	protected void paintContent(Graphics2D g)
	{
		if (records.isEmpty())
		{
			drawEmpty(g, "No kills yet");
			return;
		}

		int x = PADDING;
		int y = PADDING;
		int right = x + ROW_W - 8;
		for (BossRecord record : records)
		{
			if (y + ROW_H > naturalHeight())
			{
				break;
			}
			drawSlot(g, x, y, ROW_W, ROW_H);
			float highlight = highlightStrength(record.getPersonalBestSet());
			drawHighlight(g, x, y, ROW_W, ROW_H, highlight);

			g.setFont(FontManager.getRunescapeFont());
			String kc = "KC " + Draw.number(record.getKillCount());
			int kcW = g.getFontMetrics().stringWidth(kc);
			Draw.shadowed(g, Draw.truncate(record.getName(), g.getFontMetrics(), ROW_W - kcW - 24), x + 8, y + 16, Color.WHITE);
			Draw.shadowedRight(g, kc, right, y + 16, Draw.YELLOW);

			if (record.getPersonalBest() != null)
			{
				g.setFont(FontManager.getRunescapeSmallFont());
				String pb = "PB " + record.getPersonalBest() + (highlight > 0 ? "  New personal best!" : "");
				Draw.shadowed(g, pb, x + 8, y + 31, highlight > 0 ? Draw.GOLD : Draw.MUTED);
			}

			y += ROW_H + ROW_GAP;
		}
	}
}

package com.streamerpopoutpanels.ui;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.Locale;

/**
 * Drawing and formatting helpers shared by the popout views.
 */
public final class Draw
{
	public static final Color YELLOW = new Color(255, 255, 0);
	public static final Color GOLD = new Color(255, 200, 0);
	public static final Color GREEN = new Color(0, 255, 0);
	public static final Color RED = new Color(255, 70, 70);
	public static final Color MUTED = new Color(255, 255, 255, 140);
	private static final Color BAR_BACKGROUND = new Color(0, 0, 0, 120);

	private Draw()
	{
	}

	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	public static void shadowedRight(Graphics2D g, String text, int right, int y, Color color)
	{
		shadowed(g, text, right - g.getFontMetrics().stringWidth(text), y, color);
	}

	public static void bar(Graphics2D g, int x, int y, int w, int h, double progress, Color color)
	{
		g.setColor(BAR_BACKGROUND);
		g.fillRect(x, y, w, h);
		int filled = (int) Math.round(w * Math.max(0, Math.min(1, progress)));
		g.setColor(color);
		g.fillRect(x, y, filled, h);
	}

	public static String truncate(String text, FontMetrics fm, int width)
	{
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		String ellipsis = "...";
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + ellipsis) > width)
		{
			end--;
		}
		return text.substring(0, end) + ellipsis;
	}

	public static Color withAlpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(0, Math.min(255, alpha)));
	}

	/**
	 * 1234567 -> "1,234,567"
	 */
	public static String number(long value)
	{
		return String.format(Locale.ENGLISH, "%,d", value);
	}

	/**
	 * 1234567 -> "1.2M"
	 */
	public static String shortNumber(long value)
	{
		long abs = Math.abs(value);
		if (abs < 10_000)
		{
			return number(value);
		}
		if (abs < 1_000_000)
		{
			return String.format(Locale.ENGLISH, "%.1fK", value / 1_000d);
		}
		if (abs < 1_000_000_000)
		{
			return String.format(Locale.ENGLISH, "%.1fM", value / 1_000_000d);
		}
		return String.format(Locale.ENGLISH, "%.2fB", value / 1_000_000_000d);
	}

	/**
	 * 3725 -> "1:02:05"
	 */
	public static String duration(long seconds)
	{
		long h = seconds / 3600;
		long m = (seconds % 3600) / 60;
		long s = seconds % 60;
		return h > 0
			? String.format(Locale.ENGLISH, "%d:%02d:%02d", h, m, s)
			: String.format(Locale.ENGLISH, "%d:%02d", m, s);
	}
}

package com.streamerpopoutpanels.ui;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;

public class EquipmentView extends PopoutView
{
	private static final int CELL = 40;
	private static final int GAP = 8;
	private static final int PADDING = 8;

	/**
	 * Slot layout matching the in-game worn equipment tab, as {column, row}.
	 */
	private static final Map<EquipmentInventorySlot, int[]> LAYOUT = new EnumMap<>(EquipmentInventorySlot.class);

	static
	{
		LAYOUT.put(EquipmentInventorySlot.HEAD, new int[]{1, 0});
		LAYOUT.put(EquipmentInventorySlot.CAPE, new int[]{0, 1});
		LAYOUT.put(EquipmentInventorySlot.AMULET, new int[]{1, 1});
		LAYOUT.put(EquipmentInventorySlot.AMMO, new int[]{2, 1});
		LAYOUT.put(EquipmentInventorySlot.WEAPON, new int[]{0, 2});
		LAYOUT.put(EquipmentInventorySlot.BODY, new int[]{1, 2});
		LAYOUT.put(EquipmentInventorySlot.SHIELD, new int[]{2, 2});
		LAYOUT.put(EquipmentInventorySlot.LEGS, new int[]{1, 3});
		LAYOUT.put(EquipmentInventorySlot.GLOVES, new int[]{0, 4});
		LAYOUT.put(EquipmentInventorySlot.BOOTS, new int[]{1, 4});
		LAYOUT.put(EquipmentInventorySlot.RING, new int[]{2, 4});
	}

	public static Iterable<EquipmentInventorySlot> displayedSlots()
	{
		return LAYOUT.keySet();
	}

	private Map<EquipmentInventorySlot, BufferedImage> items = new EnumMap<>(EquipmentInventorySlot.class);

	/**
	 * @param items item image per worn slot; missing slots are empty
	 */
	public void setItems(Map<EquipmentInventorySlot, BufferedImage> items)
	{
		this.items = items;
		items.values().forEach(this::repaintWhenLoaded);
		repaint();
	}

	@Override
	protected int naturalWidth()
	{
		return 3 * CELL + 2 * GAP + PADDING * 2;
	}

	@Override
	protected int naturalHeight()
	{
		return 5 * CELL + 4 * GAP + PADDING * 2;
	}

	@Override
	protected void paintContent(Graphics2D g)
	{
		for (Map.Entry<EquipmentInventorySlot, int[]> entry : LAYOUT.entrySet())
		{
			int x = PADDING + entry.getValue()[0] * (CELL + GAP);
			int y = PADDING + entry.getValue()[1] * (CELL + GAP);
			drawSlot(g, x, y, CELL, CELL);

			BufferedImage image = items.get(entry.getKey());
			if (image != null)
			{
				drawCentered(g, image, x, y, CELL, CELL);
			}
		}
	}
}

package com.streamerpopoutpanels.ui;

import com.streamerpopoutpanels.Goal;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;

public class GoalsView extends ListView
{
	private static final int ROW_H = 46;
	private static final int ICON = 24;
	private static final Color BAR_COLOR = new Color(0x81C784);

	private final SkillIconManager skillIconManager;
	private List<Goal> goals = new ArrayList<>();
	private Map<Skill, Integer> experience = new EnumMap<>(Skill.class);
	private int totalLevel;

	public GoalsView(SkillIconManager skillIconManager)
	{
		this.skillIconManager = skillIconManager;
	}

	public void setGoals(List<Goal> goals)
	{
		this.goals = goals;
		repaint();
	}

	public void setProgress(Map<Skill, Integer> experience, int totalLevel)
	{
		this.experience = experience;
		this.totalLevel = totalLevel;
		repaint();
	}

	@Override
	protected void paintContent(Graphics2D g)
	{
		if (goals.isEmpty())
		{
			drawEmpty(g, "Add goals in the plugin settings");
			return;
		}

		int x = PADDING;
		int y = PADDING;
		int right = x + ROW_W - 8;
		for (Goal goal : goals)
		{
			if (y + ROW_H > naturalHeight())
			{
				break;
			}
			drawSlot(g, x, y, ROW_W, ROW_H);

			long current = goal.isTotalLevel() ? totalLevel : experience.getOrDefault(goal.getSkill(), 0);
			long target = goal.getTarget();
			double progress = target > 0 ? Math.min(1, current / (double) target) : 1;
			boolean done = current >= target;

			int textX = x + 8;
			if (!goal.isTotalLevel())
			{
				BufferedImage icon = skillIconManager.getSkillImage(goal.getSkill(), false);
				if (icon != null)
				{
					drawIcon(g, icon, x + 8, y + (ROW_H - ICON) / 2, ICON);
				}
				textX += ICON + 8;
			}

			g.setFont(FontManager.getRunescapeFont());
			String percent = String.format(Locale.ENGLISH, "%.1f%%", progress * 100);
			int percentW = g.getFontMetrics().stringWidth(percent);
			Draw.shadowed(g, Draw.truncate(goal.getLabel(), g.getFontMetrics(), right - textX - percentW - 6), textX, y + 15, Color.WHITE);
			Draw.shadowedRight(g, percent, right, y + 15, done ? Draw.GREEN : Draw.YELLOW);

			Draw.bar(g, textX, y + 20, right - textX, 8, progress, done ? Draw.GREEN : BAR_COLOR);

			g.setFont(FontManager.getRunescapeSmallFont());
			String detail;
			if (done)
			{
				detail = "Complete!";
			}
			else if (goal.isTotalLevel())
			{
				detail = Draw.number(target - current) + " levels to go";
			}
			else
			{
				detail = Draw.number(target - current) + " xp to go";
			}
			Draw.shadowed(g, detail, textX, y + 40, done ? Draw.GREEN : Draw.MUTED);

			y += ROW_H + ROW_GAP;
		}
	}
}

package com.streamerpopoutpanels.ui;

import java.awt.Graphics2D;
