package com.streamerpopoutpanels.ui;

import java.awt.Graphics2D;
import javax.swing.Timer;
import net.runelite.client.ui.FontManager;

/**
 * Base for list-style views. These scale to the window width only and show as many rows as
 * fit in the window height. Also supports fading highlights on new entries.
 */
public abstract class ListView extends PopoutView
{
	protected static final int WIDTH = 300;
	protected static final int PADDING = 6;
	protected static final int ROW_GAP = 4;
	protected static final int ROW_W = WIDTH - PADDING * 2;

	/**
	 * Drives the highlight fade; only runs while something is highlighted.
	 */
	private final Timer fadeTimer;
	private long highlightMillis;

	protected ListView()
	{
		fadeTimer = new Timer(50, e ->
		{
			repaint();
			if (!anyHighlighted())
			{
				((Timer) e.getSource()).stop();
			}
		});
	}

	@Override
	protected int naturalWidth()
	{
		return WIDTH;
	}

	/**
	 * Follows the window's aspect ratio, so the base class ends up scaling to the window width.
	 */
	@Override
	protected int naturalHeight()
	{
		return Math.max(1, getHeight() * WIDTH / Math.max(1, getWidth()));
	}

	public void setHighlightSeconds(int seconds)
	{
		highlightMillis = seconds * 1000L;
		contentChanged();
	}

	@Override
	public void stop()
	{
		fadeTimer.stop();
	}

	/**
	 * Call after the view's data changes.
	 */
	protected void contentChanged()
	{
		if (anyHighlighted())
		{
			fadeTimer.start();
		}
		repaint();
	}

	/**
	 * @return whether any entry currently has a highlight
	 */
	protected boolean anyHighlighted()
	{
		return false;
	}

	/**
	 * @return highlight strength from 1 (brand new) fading to 0
	 */
	protected float highlightStrength(long timestamp)
	{
		long age = System.currentTimeMillis() - timestamp;
		if (highlightMillis <= 0 || age < 0 || age >= highlightMillis)
		{
			return 0;
		}
		return 1f - age / (float) highlightMillis;
	}

	protected static void drawHighlight(Graphics2D g, int x, int y, int w, int h, float strength)
	{
		if (strength <= 0)
		{
			return;
		}
		g.setColor(Draw.withAlpha(Draw.GOLD, (int) (70 * strength)));
		g.fillRoundRect(x, y, w, h, 6, 6);
		g.setColor(Draw.withAlpha(Draw.GOLD, (int) (255 * strength)));
		g.drawRoundRect(x, y, w - 1, h - 1, 6, 6);
	}

	protected static void drawEmpty(Graphics2D g, String text)
	{
		g.setFont(FontManager.getRunescapeFont());
		g.setColor(Draw.MUTED);
		g.drawString(text, (WIDTH - g.getFontMetrics().stringWidth(text)) / 2, PADDING + 22);
	}
}

package com.streamerpopoutpanels.ui;

import com.streamerpopoutpanels.tracker.LootSession;
import java.awt.Color;
import java.awt.Graphics2D;
import java.util.Collections;
import net.runelite.client.ui.FontManager;

public class LootView extends ListView
{
	private static final int HEADER_H = 36;
	private static final int LAST_H = 58;
	private static final int ITEM_W = 38;
	private static final int ROW_H = 38;

	private LootSession session = new LootSession(0, 0, null, Collections.emptyList());

	public void setSession(LootSession session)
	{
		this.session = session;
		if (session.getLastLoot() != null)
		{
			session.getLastLoot().getItems().forEach(item -> repaintWhenLoaded(item.getImage()));
		}
		session.getBestDrops().forEach(item -> repaintWhenLoaded(item.getImage()));
		repaint();
	}

	@Override
	protected void paintContent(Graphics2D g)
	{
		int x = PADDING;
		int y = PADDING;
		int right = x + ROW_W - 8;

		// Header: session total
		drawSlot(g, x, y, ROW_W, HEADER_H);
		g.setFont(FontManager.getRunescapeSmallFont());
		Draw.shadowed(g, "Session loot", x + 8, y + 14, Draw.MUTED);
		Draw.shadowedRight(g, session.getLootCount() + (session.getLootCount() == 1 ? " loot" : " loots"), right, y + 14, Draw.MUTED);
		g.setFont(FontManager.getRunescapeBoldFont());
		Draw.shadowed(g, Draw.shortNumber(session.getTotalValue()) + " gp", x + 8, y + 30, Draw.GOLD);
		y += HEADER_H + ROW_GAP;

		LootSession.Loot last = session.getLastLoot();
		if (last == null)
		{
			g.setFont(FontManager.getRunescapeFont());
			g.setColor(Draw.MUTED);
			String text = "No loot yet";
			g.drawString(text, (WIDTH - g.getFontMetrics().stringWidth(text)) / 2, y + 20);
			return;
		}

		// Most recent loot with its item icons
		if (y + LAST_H <= naturalHeight())
		{
			drawSlot(g, x, y, ROW_W, LAST_H);
			g.setFont(FontManager.getRunescapeSmallFont());
			String value = Draw.shortNumber(last.getValue()) + " gp";
			int valueW = g.getFontMetrics().stringWidth(value);
			Draw.shadowed(g, Draw.truncate("Last: " + last.getSource(), g.getFontMetrics(), ROW_W - valueW - 24), x + 8, y + 14, Color.WHITE);
			Draw.shadowedRight(g, value, right, y + 14, Draw.GOLD);

			int itemX = x + 4;
			for (LootSession.LootItem item : last.getItems())
			{
				if (itemX + ITEM_W > x + ROW_W)
				{
					break;
				}
				drawCentered(g, item.getImage(), itemX, y + 18, ITEM_W, 38);
				itemX += ITEM_W;
			}
			y += LAST_H + ROW_GAP;
		}

		if (session.getBestDrops().isEmpty() || y + 16 + ROW_H > naturalHeight())
		{
			return;
		}

		g.setFont(FontManager.getRunescapeSmallFont());
		Draw.shadowed(g, "Best drops", x + 2, y + 12, Draw.MUTED);
		y += 16;

		for (LootSession.LootItem item : session.getBestDrops())
		{
			if (y + ROW_H > naturalHeight())
			{
				break;
			}
			drawSlot(g, x, y, ROW_W, ROW_H);
			drawCentered(g, item.getImage(), x + 2, y + 1, 40, 36);

			int textX = x + 46;
			g.setFont(FontManager.getRunescapeSmallFont());
			String value = Draw.shortNumber(item.getValue()) + " gp";
			int valueW = g.getFontMetrics().stringWidth(value);
			String name = item.getQuantity() > 1 ? Draw.number(item.getQuantity()) + " x " + item.getName() : item.getName();
			Draw.shadowed(g, Draw.truncate(name, g.getFontMetrics(), right - textX - valueW - 6), textX, y + 16, Color.WHITE);
			Draw.shadowedRight(g, value, right, y + 16, Draw.GOLD);
			Draw.shadowed(g, Draw.truncate(item.getSource(), g.getFontMetrics(), right - textX), textX, y + 30, Draw.MUTED);

			y += ROW_H + ROW_GAP;
		}
	}
}

package com.streamerpopoutpanels.ui;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Base class for popout panel content. Subclasses draw at a fixed "natural" size and the
 * drawing is scaled to fit the window, so streamers can resize the window freely.
 * All methods must be called on the Swing event dispatch thread.
 */
public abstract class PopoutView extends JComponent
{
	protected static final Color SLOT_FILL = new Color(255, 255, 255, 18);
	protected static final Color SLOT_BORDER = new Color(255, 255, 255, 40);

	private Color backgroundColor = Color.BLACK;

	protected PopoutView()
	{
		setOpaque(true);
	}

	public void setBackgroundColor(Color color)
	{
		backgroundColor = color;
		repaint();
	}

	/**
	 * Adds an entry to the view's right-click menu.
	 */
	public void addMenuAction(String label, Runnable action)
	{
		JPopupMenu menu = getComponentPopupMenu();
		if (menu == null)
		{
			menu = new JPopupMenu();
			setComponentPopupMenu(menu);
		}
		JMenuItem item = new JMenuItem(label);
		item.addActionListener(e -> action.run());
		menu.add(item);
	}

	/**
	 * Stops any timers the view owns. Called when the plugin shuts down.
	 */
	public void stop()
	{
	}

	/**
	 * Size the content is drawn at before scaling.
	 */
	protected abstract int naturalWidth();

	protected abstract int naturalHeight();

	protected abstract void paintContent(Graphics2D g);

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setColor(backgroundColor);
			g.fillRect(0, 0, getWidth(), getHeight());

			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);

			double scale = Math.min(getWidth() / (double) naturalWidth(), getHeight() / (double) naturalHeight());
			if (scale <= 0)
			{
				return;
			}
			g.translate((getWidth() - naturalWidth() * scale) / 2, (getHeight() - naturalHeight() * scale) / 2);
			g.scale(scale, scale);
			paintContent(g);
		}
		finally
		{
			g.dispose();
		}
	}

	/**
	 * Repaint once an asynchronously loaded item image is ready.
	 */
	protected void repaintWhenLoaded(BufferedImage image)
	{
		if (image instanceof AsyncBufferedImage)
		{
			((AsyncBufferedImage) image).onLoaded(this::repaint);
		}
	}

	protected static void drawCentered(Graphics2D g, Image image, int x, int y, int w, int h)
	{
		g.drawImage(image, x + (w - image.getWidth(null)) / 2, y + (h - image.getHeight(null)) / 2, null);
	}

	/**
	 * Draws an image scaled to a square, smoothing it so small skill icons don't look jagged.
	 */
	protected static void drawIcon(Graphics2D g, Image image, int x, int y, int size)
	{
		Object old = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		int w = image.getWidth(null);
		int h = image.getHeight(null);
		double s = Math.min(size / (double) w, size / (double) h);
		int dw = (int) (w * s);
		int dh = (int) (h * s);
		g.drawImage(image, x + (size - dw) / 2, y + (size - dh) / 2, dw, dh, null);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, old);
	}

	protected static void drawSlot(Graphics2D g, int x, int y, int w, int h)
	{
		g.setColor(SLOT_FILL);
		g.fillRoundRect(x, y, w, h, 6, 6);
		g.setColor(SLOT_BORDER);
		g.drawRoundRect(x, y, w - 1, h - 1, 6, 6);
	}
}

package com.streamerpopoutpanels.ui;

import com.streamerpopoutpanels.PanelType;
import java.awt.BorderLayout;
import java.awt.GraphicsDevice;
import java.awt.GraphicsEnvironment;
import java.awt.Rectangle;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.function.Consumer;
import javax.swing.JFrame;
import javax.swing.WindowConstants;

/**
 * A standalone window holding one popout view, meant to be captured by OBS "Window Capture".
 */
public class PopoutWindow extends JFrame
{
	public PopoutWindow(PanelType type, PopoutView view, Rectangle savedBounds, boolean alwaysOnTop,
		Runnable onUserClose, Consumer<Rectangle> onBoundsChanged)
	{
		super(type.getWindowTitle());
		setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);
		setLayout(new BorderLayout());
		add(view, BorderLayout.CENTER);
		setAlwaysOnTop(alwaysOnTop);

		if (savedBounds != null && isOnScreen(savedBounds))
		{
			setBounds(savedBounds);
		}
		else
		{
			setSize(type.getDefaultWidth(), type.getDefaultHeight());
			setLocationByPlatform(true);
		}

		addWindowListener(new WindowAdapter()
		{
			@Override
			public void windowClosing(WindowEvent e)
			{
				onUserClose.run();
			}
		});

		addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentMoved(ComponentEvent e)
			{
				reportBounds(onBoundsChanged);
			}

			@Override
			public void componentResized(ComponentEvent e)
			{
				reportBounds(onBoundsChanged);
			}
		});
	}

	private void reportBounds(Consumer<Rectangle> onBoundsChanged)
	{
		// Minimised windows are moved far off screen, so only remember normal bounds
		if (isVisible() && getExtendedState() == NORMAL)
		{
			onBoundsChanged.accept(getBounds());
		}
	}

	private static boolean isOnScreen(Rectangle bounds)
	{
		for (GraphicsDevice device : GraphicsEnvironment.getLocalGraphicsEnvironment().getScreenDevices())
		{
			if (device.getDefaultConfiguration().getBounds().intersects(bounds))
			{
				return true;
			}
		}
		return false;
	}
}

package com.streamerpopoutpanels.ui;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;

public class SkillsView extends PopoutView
{
	/**
	 * Skills in the order the in-game skills tab shows them, left to right, top to bottom.
	 */
	public static final Skill[] LAYOUT = {
		Skill.ATTACK, Skill.HITPOINTS, Skill.MINING,
		Skill.STRENGTH, Skill.AGILITY, Skill.SMITHING,
		Skill.DEFENCE, Skill.HERBLORE, Skill.FISHING,
		Skill.RANGED, Skill.THIEVING, Skill.COOKING,
		Skill.PRAYER, Skill.CRAFTING, Skill.FIREMAKING,
		Skill.MAGIC, Skill.FLETCHING, Skill.WOODCUTTING,
		Skill.RUNECRAFT, Skill.SLAYER, Skill.FARMING,
		Skill.CONSTRUCTION, Skill.HUNTER, Skill.SAILING,
	};

	private static final int COLUMNS = 3;
	private static final int CELL_W = 62;
	private static final int CELL_H = 32;
	private static final int GAP = 3;
	private static final int PADDING = 6;

	private final SkillIconManager skillIconManager;

	private Map<Skill, Integer> realLevels = new EnumMap<>(Skill.class);
	private Map<Skill, Integer> boostedLevels = new EnumMap<>(Skill.class);
	private int totalLevel;

	public SkillsView(SkillIconManager skillIconManager)
	{
		this.skillIconManager = skillIconManager;
	}

	public void setLevels(Map<Skill, Integer> realLevels, Map<Skill, Integer> boostedLevels, int totalLevel)
	{
		this.realLevels = realLevels;
		this.boostedLevels = boostedLevels;
		this.totalLevel = totalLevel;
		repaint();
	}

	private int rows()
	{
		return (LAYOUT.length + COLUMNS - 1) / COLUMNS;
	}

	@Override
	protected int naturalWidth()
	{
		return COLUMNS * CELL_W + (COLUMNS - 1) * GAP + PADDING * 2;
	}

	@Override
	protected int naturalHeight()
	{
		// One extra row for the total level
		int rows = rows() + 1;
		return rows * CELL_H + (rows - 1) * GAP + PADDING * 2;
	}

	@Override
	protected void paintContent(Graphics2D g)
	{
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();

		for (int i = 0; i < LAYOUT.length; i++)
		{
			Skill skill = LAYOUT[i];
			int x = PADDING + (i % COLUMNS) * (CELL_W + GAP);
			int y = PADDING + (i / COLUMNS) * (CELL_H + GAP);
			drawSlot(g, x, y, CELL_W, CELL_H);

			BufferedImage icon = skillIconManager.getSkillImage(skill, true);
			if (icon != null)
			{
				drawCentered(g, icon, x + 2, y, 24, CELL_H);
			}

			int real = realLevels.getOrDefault(skill, 1);
			int boosted = boostedLevels.getOrDefault(skill, real);
			Color boostedColor = boosted > real ? Draw.GREEN : boosted < real ? Draw.RED : Draw.YELLOW;

			String boostedText = String.valueOf(boosted);
			String realText = String.valueOf(real);
			int textX = x + 30;
			Draw.shadowed(g, boostedText, textX + 14 - fm.stringWidth(boostedText) / 2, y + 14, boostedColor);
			Draw.shadowed(g, realText, textX + 22 - fm.stringWidth(realText) / 2, y + 27, Draw.YELLOW);
		}

		int totalY = PADDING + rows() * (CELL_H + GAP);
		int totalW = naturalWidth() - PADDING * 2;
		drawSlot(g, PADDING, totalY, totalW, CELL_H);
		g.setFont(FontManager.getRunescapeFont());
		fm = g.getFontMetrics();
		String total = "Total level: " + totalLevel;
		Draw.shadowed(g, total, PADDING + (totalW - fm.stringWidth(total)) / 2, totalY + (CELL_H + fm.getAscent()) / 2 - 2, Draw.YELLOW);
	}
}

package com.streamerpopoutpanels.ui;

import com.streamerpopoutpanels.tracker.SlayerTask;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;

public class SlayerView extends PopoutView
{
	private static final int WIDTH = 280;
	private static final int HEIGHT = 108;
	private static final int PADDING = 6;
	private static final int ICON = 32;
	private static final Color BAR_COLOR = new Color(0xE57373);

	private final SkillIconManager skillIconManager;
	private SlayerTask task;

	public SlayerView(SkillIconManager skillIconManager)
	{
		this.skillIconManager = skillIconManager;
	}

	public void setTask(SlayerTask task)
	{
		this.task = task;
		repaint();
	}

	@Override
	protected int naturalWidth()
	{
		return WIDTH;
	}

	@Override
	protected int naturalHeight()
	{
		return HEIGHT;
	}

	@Override
	protected void paintContent(Graphics2D g)
	{
		int x = PADDING;
		int y = PADDING;
		int w = WIDTH - PADDING * 2;
		int h = HEIGHT - PADDING * 2;
		int right = x + w - 8;
		drawSlot(g, x, y, w, h);

		BufferedImage icon = skillIconManager.getSkillImage(Skill.SLAYER, false);
		if (icon != null)
		{
			drawIcon(g, icon, x + 8, y + 8, ICON);
		}

		int textX = x + 8 + ICON + 10;
		g.setFont(FontManager.getRunescapeSmallFont());
		Draw.shadowed(g, "Slayer task", textX, y + 16, Draw.MUTED);

		if (task == null || task.getName() == null)
		{
			g.setFont(FontManager.getRunescapeBoldFont());
			Draw.shadowed(g, task == null ? "Log in to see your task" : "No slayer task", textX, y + 34, Color.WHITE);
		}
		else
		{
			g.setFont(FontManager.getRunescapeBoldFont());
			Draw.shadowed(g, Draw.truncate(task.getName(), g.getFontMetrics(), right - textX), textX, y + 34, Color.WHITE);

			g.setFont(FontManager.getRunescapeSmallFont());
			if (task.getLocation() != null)
			{
				Draw.shadowed(g, Draw.truncate(task.getLocation(), g.getFontMetrics(), right - textX), textX, y + 48, Draw.MUTED);
			}

			int barY = y + 54;
			double done = task.getOriginal() > 0 ? 1 - task.getRemaining() / (double) task.getOriginal() : 0;
			Draw.bar(g, x + 8, barY, w - 16, 8, done, BAR_COLOR);
			Draw.shadowed(g, Draw.number(task.getRemaining()) + " left", x + 8, barY + 22, Draw.YELLOW);
			if (task.getOriginal() > 0)
			{
				Draw.shadowedRight(g, "of " + Draw.number(task.getOriginal()), right, barY + 22, Draw.MUTED);
			}
		}

		if (task != null)
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			String footer = "Points: " + Draw.number(task.getPoints()) + "    Streak: " + Draw.number(task.getStreak());
			Draw.shadowedRight(g, footer, right, y + 16, Draw.MUTED);
		}
	}
}

package com.streamerpopoutpanels.ui;

import com.streamerpopoutpanels.tracker.Vitals;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;

public class VitalsView extends PopoutView
{
	private static final int WIDTH = 260;
	private static final int PADDING = 6;
	private static final int ROW_H = 30;
	private static final int ROW_GAP = 4;
	private static final int ROWS = 3;
	private static final int ICON = 20;
	private static final int BAR_H = 18;

	private static final Color HITPOINTS_COLOR = new Color(200, 40, 20);
	private static final Color POISONED_COLOR = new Color(0, 145, 0);
	private static final Color VENOMED_COLOR = new Color(0, 90, 70);
	private static final Color DISEASED_COLOR = new Color(200, 150, 40);
	private static final Color PRAYER_COLOR = new Color(40, 170, 210);
	private static final Color RUN_COLOR = new Color(210, 190, 50);
	private static final Color STAMINA_COLOR = new Color(170, 115, 60);

	private final SkillIconManager skillIconManager;
	private Vitals vitals;

	public VitalsView(SkillIconManager skillIconManager)
	{
		this.skillIconManager = skillIconManager;
	}

	public void setVitals(Vitals vitals)
	{
		this.vitals = vitals;
		repaint();
	}

	@Override
	protected int naturalWidth()
	{
		return WIDTH;
	}

	@Override
	protected int naturalHeight()
	{
		return ROWS * ROW_H + (ROWS - 1) * ROW_GAP + PADDING * 2;
	}

	@Override
	protected void paintContent(Graphics2D g)
	{
		Vitals v = vitals != null ? vitals : new Vitals(0, 0, Vitals.HitpointsStatus.NORMAL, 0, 0, 0, false);
		int y = PADDING;

		String hpSuffix;
		Color hpColor;
		switch (v.getStatus())
		{
			case POISONED:
				hpSuffix = "  Poisoned";
				hpColor = POISONED_COLOR;
				break;
			case VENOMED:
				hpSuffix = "  Venomed";
				hpColor = VENOMED_COLOR;
				break;
			case DISEASED:
				hpSuffix = "  Diseased";
				hpColor = DISEASED_COLOR;
				break;
			default:
				hpSuffix = "";
				hpColor = HITPOINTS_COLOR;
		}
		drawRow(g, y, Skill.HITPOINTS, v.getHitpoints(), v.getMaxHitpoints(),
			v.getHitpoints() + " / " + v.getMaxHitpoints() + hpSuffix, hpColor);
		y += ROW_H + ROW_GAP;

		drawRow(g, y, Skill.PRAYER, v.getPrayer(), v.getMaxPrayer(),
			v.getPrayer() + " / " + v.getMaxPrayer(), PRAYER_COLOR);
		y += ROW_H + ROW_GAP;

		drawRow(g, y, Skill.AGILITY, v.getRunEnergy(), 100,
			v.getRunEnergy() + "%" + (v.isStaminaActive() ? "  Stamina" : ""), v.isStaminaActive() ? STAMINA_COLOR : RUN_COLOR);
	}

	private void drawRow(Graphics2D g, int y, Skill iconSkill, int value, int max, String text, Color color)
	{
		int x = PADDING;
		int w = WIDTH - PADDING * 2;
		drawSlot(g, x, y, w, ROW_H);

		BufferedImage icon = skillIconManager.getSkillImage(iconSkill, false);
		if (icon != null)
		{
			drawIcon(g, icon, x + 6, y + (ROW_H - ICON) / 2, ICON);
		}

		int barX = x + 6 + ICON + 6;
		int barW = x + w - 6 - barX;
		int barY = y + (ROW_H - BAR_H) / 2;
		// Boosted levels (e.g. overheal) can exceed the max, so clamp the fill
		Draw.bar(g, barX, barY, barW, BAR_H, max > 0 ? value / (double) max : 0, color);
		g.setColor(SLOT_BORDER);
		g.drawRect(barX, barY, barW - 1, BAR_H - 1);

		g.setFont(FontManager.getRunescapeSmallFont());
		int textW = g.getFontMetrics().stringWidth(text);
		Draw.shadowed(g, text, barX + (barW - textW) / 2, barY + 13, Color.WHITE);
	}
}

package com.streamerpopoutpanels.ui;

import com.streamerpopoutpanels.tracker.XpSession;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Collections;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.FontManager;

public class XpTrackerView extends ListView
{
	private static final int HEADER_H = 36;
	private static final int ROW_H = 44;
	private static final int ICON = 24;
	private static final Color BAR_COLOR = new Color(0x4FC3F7);

	private final SkillIconManager skillIconManager;
	private XpSession session = new XpSession(0, 0, 0, Collections.emptyList());

	public XpTrackerView(SkillIconManager skillIconManager)
	{
		this.skillIconManager = skillIconManager;
	}

	public void setSession(XpSession session)
	{
		this.session = session;
		repaint();
	}

	@Override
	protected void paintContent(Graphics2D g)
	{
		int x = PADDING;
		int y = PADDING;
		int right = x + ROW_W - 8;

		// Header: session time and totals
		drawSlot(g, x, y, ROW_W, HEADER_H);
		g.setFont(FontManager.getRunescapeSmallFont());
		Draw.shadowed(g, "Session time", x + 8, y + 14, Draw.MUTED);
		Draw.shadowedRight(g, Draw.shortNumber(session.getTotalPerHour()) + " xp/hr", right, y + 14, Draw.MUTED);
		g.setFont(FontManager.getRunescapeBoldFont());
		Draw.shadowed(g, Draw.duration(session.getElapsedSeconds()), x + 8, y + 30, Color.WHITE);
		Draw.shadowedRight(g, "+" + Draw.number(session.getTotalGained()) + " xp", right, y + 30, Draw.YELLOW);
		y += HEADER_H + ROW_GAP;

		if (session.getSkills().isEmpty())
		{
			g.setFont(FontManager.getRunescapeFont());
			g.setColor(Draw.MUTED);
			String text = "Gain some XP to start tracking";
			g.drawString(text, (WIDTH - g.getFontMetrics().stringWidth(text)) / 2, y + 20);
			return;
		}

		for (XpSession.SkillGain skill : session.getSkills())
		{
			if (y + ROW_H > naturalHeight())
			{
				break;
			}

			drawSlot(g, x, y, ROW_W, ROW_H);
			BufferedImage icon = skillIconManager.getSkillImage(skill.getSkill(), false);
			if (icon != null)
			{
				drawIcon(g, icon, x + 8, y + (ROW_H - ICON) / 2, ICON);
			}

			int textX = x + 8 + ICON + 8;
			g.setFont(FontManager.getRunescapeFont());
			Draw.shadowed(g, skill.getSkill().getName(), textX, y + 15, Color.WHITE);
			Draw.shadowedRight(g, "+" + Draw.number(skill.getGained()), right, y + 15, Draw.YELLOW);

			g.setFont(FontManager.getRunescapeSmallFont());
			Draw.shadowed(g, "Lvl " + skill.getLevel() + "  " + Draw.shortNumber(skill.getPerHour()) + "/hr", textX, y + 28, Draw.MUTED);
			String ttl = skill.getSecondsToLevel() >= 0 ? Draw.duration(skill.getSecondsToLevel()) + " to level" : "";
			Draw.shadowedRight(g, ttl, right, y + 28, Draw.MUTED);

			Draw.bar(g, textX, y + 33, right - textX, 5, skill.getLevelProgress(), BAR_COLOR);

			y += ROW_H + ROW_GAP;
		}
	}
}

package com.streamerpopoutpanels;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import net.runelite.client.util.Text;
import org.junit.Test;

public class AchievementParserTest
{
	private static Achievement parse(String message)
	{
		return AchievementParser.parse(Text.removeTags(message), 0);
	}

	private static void assertAchievement(String message, AchievementType type, String text)
	{
		Achievement a = parse(message);
		assertEquals(type, a.getType());
		assertEquals(text, a.getText());
	}

	@Test
	public void collectionLog()
	{
		assertAchievement("New item added to your collection log: <col=ef1020>Abyssal whip</col>",
			AchievementType.COLLECTION_LOG, "Abyssal whip");
	}

	@Test
	public void quest()
	{
		assertAchievement("Congratulations, you've completed a quest: <col=0a0ca5>Cook's Assistant</col>",
			AchievementType.QUEST, "Cook's Assistant");
	}

	@Test
	public void combatTask()
	{
		assertAchievement("Congratulations, you've completed an easy combat task: <col=06600c>Noxious Foe</col> (1 point).",
			AchievementType.COMBAT_TASK, "Easy: Noxious Foe");
		assertAchievement("Congratulations, you've completed a grandmaster combat task: <col=06600c>Perfect Olm (Solo)</col> (6 points).",
			AchievementType.COMBAT_TASK, "Grandmaster: Perfect Olm (Solo)");
	}

	@Test
	public void diary()
	{
		assertAchievement("Congratulations! You have completed all of the hard tasks in the Ardougne area. Speak to Two-pints to claim your reward.",
			AchievementType.DIARY, "Ardougne Hard");
	}

	@Test
	public void drops()
	{
		assertAchievement("<col=ef1020>Valuable drop: 1 x Dragon pickaxe (1,234,567 coins)</col>",
			AchievementType.DROP, "1 x Dragon pickaxe (1,234,567 coins)");
		assertAchievement("<col=ef1020>Untradeable drop: Pet snakeling</col>",
			AchievementType.DROP, "Pet snakeling");
	}

	@Test
	public void pets()
	{
		assertAchievement("You have a funny feeling like you're being followed.", AchievementType.PET, "New pet!");
		assertAchievement("You feel something weird sneaking into your backpack.", AchievementType.PET, "New pet!");
		assertAchievement("You have a funny feeling like you would have been followed...", AchievementType.PET, "Pet drop (duplicate)");
	}

	@Test
	public void ignoresOtherMessages()
	{
		assertNull(parse("Welcome to Old School RuneScape."));
		assertNull(parse("Your Zulrah kill count is: <col=ff0000>12</col>."));
	}
}

package com.streamerpopoutpanels;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.List;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import org.junit.Test;

public class GoalParserTest
{
	private static Goal single(String text)
	{
		List<Goal> goals = GoalParser.parse(text);
		return goals.isEmpty() ? null : goals.get(0);
	}

	@Test
	public void levelGoal()
	{
		Goal goal = single("Slayer 99");
		assertEquals(Skill.SLAYER, goal.getSkill());
		assertEquals(Experience.getXpForLevel(99), goal.getTarget());
		assertEquals("Slayer level 99", goal.getLabel());
	}

	@Test
	public void xpGoals()
	{
		assertEquals(50_000_000, single("Fishing 50m").getTarget());
		assertEquals(250_000, single("fishing 250k").getTarget());
		assertEquals(13_034_431, single("Fishing 13,034,431 xp").getTarget());
		assertEquals(500, single("Fishing 500").getTarget());
		assertEquals(200_000_000, single("Fishing 500m").getTarget());
		assertEquals("Fishing 13.5M xp", single("Fishing 13.5m").getLabel());
	}

	@Test
	public void totalLevel()
	{
		Goal goal = single("Total 2000");
		assertTrue(goal.isTotalLevel());
		assertEquals(2000, goal.getTarget());
	}

	@Test
	public void aliasesAndSeparators()
	{
		List<Goal> goals = GoalParser.parse("hp 99, rc 77\nsailing 50");
		assertEquals(3, goals.size());
		assertEquals(Skill.HITPOINTS, goals.get(0).getSkill());
		assertEquals(Skill.RUNECRAFT, goals.get(1).getSkill());
		assertEquals(Skill.SAILING, goals.get(2).getSkill());
	}

	@Test
	public void invalid()
	{
		assertNull(single("Dancing 99"));
		assertNull(single("Slayer"));
		assertNull(single(""));
		assertNull(single("Slayer 1"));
		assertTrue(GoalParser.parse(null).isEmpty());
	}
}

